<template>
    <div class="chekcbox" @click="clickHandle" :class="{checked:checked}">
        <gouImg v-if="checked" v-bind="{color: '#fff',width:'12px',height:'12px'}"/>
    </div>
</template>

<script>
export default {
    props: {
        propChecked: {
            type: Boolean,
            default: false
        },
        propValue: [String, Number]
    },

    data() {
        return {
            checked: this.propChecked,
            value: this.propValue
        };
    },

    watch: {
        propChecked() {
            this.checked = this.propChecked;
        }
    },

    methods: {
        clickHandle(e) {
            this.checked = !this.checked;
            this.$emit("change", this.checked, this.value, e);
        }
    }
};
</script>

<style scoped>
.chekcbox {
    width: 12px;
    height: 12px;
    background-color: #fff;
    border: 1px solid #333;
    border-radius: 2px;
    cursor: pointer;
}

.chekcbox:hover {
    border: 1px solid rgb(0, 122, 255);
    box-shadow: 0 0 3px rgba(0, 122, 255, 0.5);
}

.chekcbox.checked {
    background-color: rgb(0, 122, 255);
    border: none;
}
</style>