<template>
    <div
        class="time-input"
        :class="{readonly:readonly,invisible:invisible}"
        @dblclick="dblclickHandle"
        @mousedown.stop
        @click="clickHandle"
    >
        <div v-if="readonly || invisible" class="readonly-text">{{value}}</div>
        <template v-else>
            <input :name="options.field" v-model="value" :readonly="editable" ref="input" />
            <div class="time-input-icon" v-on:click.stop="popTimePicker">
                <clock color="#777" />
            </div>
        </template>
    </div>
</template>
<script>
import jQuery from "jquery";
import Vue from "vue";
import Gikam from "../../../../core/gikam-core";
import timePicker from "./timePicker";

export default {
    props: {
        options: Object,
        propValue: String,
        rowIndex: Number,
        //编辑器中的边框等样式是否显示出来
        propInvisible: {
            type: Boolean,
            default: false
        }
    },

    computed: {
        time() {
            let tempDate = Gikam.DateUtils.formatter(new Date(), "yyyy-MM-dd");
            return this.value
                ? Gikam.DateUtils.toDateTime(tempDate + " " + this.value.trim())
                : "";
        },
        editable() {
            return this.options.editable === true ? "" : "readonly";
        }
    },

    data() {
        return {
            readonly: void 0,
            field: void 0,
            value: void 0,
            invisible: this.propInvisible
        };
    },

    created() {
        Object.assign(this, this.options);
        if (Gikam.isNotEmpty(this.propValue)) {
            this.value = this.propValue;
        }
    },

    watch: {
        value() {
            this.$emit("change", this.options.field, this.value, this.rowIndex);
        },

        propValue(val) {
            this.value = val;
        }
    },

    methods: {
        cleanTimePicker() {
            Gikam.timePicker.destroy();
        },

        popTimePicker() {
            let _this = this;

            if (Gikam.timePicker) {
                this.cleanTimePicker();
            }

            Gikam.timePicker = new Vue({
                el: Gikam.createDom("div", document.body),
                components: { timePicker },
                methods: {
                    destroy() {
                        jQuery(this.$el).remove();
                        this.$destroy();
                        Gikam.timePicker = null;
                    }
                },
                render() {
                    return <time-picker timeInput={_this} />;
                }
            });
        },

        dblclickHandle() {
            this.$emit("dblclick", this);
        },

        focus() {
            this.$refs.input.focus();
        },

        clickHandle() {
            this.$emit("click", this);
        }
    }
};
</script>

<style scoped>
.time-input {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: stretch;
    color: #666;
    font-size: 12px;
}

.time-input.readonly {
    display: flex;
    align-items: center;
}

.time-input input,
.time-input .readonly-text {
    width: 100%;
    height: 100%;
    border-radius: 4px;
    border: 1px solid #d9d9d9;
    padding-right: 30px;
    padding-left: 8px;
    color: rgba(0, 0, 0, 0.65);
    font-size: 12px;
}

.time-input .readonly-text {
    background-color: #f4f4f4;
    display: flex;
    align-items: center;
}

.time-input input:focus {
    border: 1px solid rgba(0, 122, 255, 0.5);
}

.time-input .time-input-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    cursor: pointer;
    margin-left: -30px;
}

.time-input .time-input-icon svg {
    width: 16px;
    height: 16px;
}

.invisible .readonly-text {
    background-color: transparent;
    border: none;
}
</style>