import Base from '../../../base';
import Gikam from "../../../../core/gikam-core";
import Vue from 'vue';

let defaultOptions = {
    url: void 0,
    baseUrl: void 0,
    renderTo: void 0
};

export default class HolidaySetting extends Base {

    constructor(options) {
        super(options);
        this.initialize(options, defaultOptions).init();
    }

    createViewModel() {
        const _this = this;
        this.holidaySetting = new Vue({
            el: Gikam.createDom('div', this.options.renderTo),
            render() {
                return <holiday-setting options={this.options}></holiday-setting>
            },
            components: {
                holidaySetting: () => import('../vue/holidaySetting.vue')
            },
            data() {
                return {
                    options: _this.options
                };
            }
        });

        this.bindInstance(this.holidaySetting.$el);
    }

    init() {
        this.createViewModel();
    }
}