<template>
    <div
        class="text-input"
        :class="{'validate-error':!validateResult,readonly:readonly,invisible:invisible}"
        @dblclick="dblclickHandle"
        @click="clickHandle"
        @mousedown.stop
    >
        <div v-if="readonly || invisible" class="readonly-text">{{value}}</div>
        <input
            v-else
            :name="field"
            v-model.lazy.trim="value"
            @focus="focusHandle"
            @blur="blurHandle"
            @keydown="keydownHandle"
            @keyup="keyupHandle"
            @input="inputHandle"
            ref="input"
        />
        <div class="validate-error-icon" v-if="validateResult===false" @click.stop>
            <info-image @mouseenter.stop="errorIconMouseenter" @mouseleave="errorIconMouseleave"></info-image>
        </div>
    </div>
</template>
<script>
import Gikam from "../../../core/gikam-core";
import BaseField from "../baseField/baseField.vue";
import infoImage from "../img/info.vue";

export default {
    name: "textInput",
    props: {
        options: Object,
        propValue: [String, Number],
        rowIndex: Number,
        cellIndex: Number,
        propReadonly: {
            type: Boolean,
            default: void 0
        },
        //编辑器中的边框等样式是否显示出来
        propInvisible: {
            type: Boolean,
            default: false
        }
    },
    extends: BaseField,
    components: { infoImage },

    data() {
        return {
            validateResult: true,
            readonly: Gikam.isNotEmpty(this.propReadonly)
                ? this.propReadonly
                : this.options.readonly,
            field: this.options.field,
            valueIsChange: false,
            value: this.propValue,
            invisible: this.propInvisible
        };
    },

    watch: {
        value(val) {
            this.valueIsChange = true;
            if (this.validate()) {
                this.validateResult = true;
                this.$emit("change", this.options.field, val, this.rowIndex);
            } else {
                this.validateResult = false;
            }
        },

        propValue(val) {
            this.value = val;
        },

        propInvisible(val) {
            this.invisible = val;
        }
    },

    methods: {
        focusHandle() {
            this.validateResult = true;
            this.$emit("focus", this.options.field, this.value, this.rowIndex);
        },

        blurHandle() {
            if (!this.valueIsChange && !this.validate()) {
                this.validateResult = false;
            }
            this.valueIsChange = false;
        },

        keydownHandle(e) {
            this.$emit("keydown", e);
            if (this.options.onKeyDown) {
                this.options.onKeyDown(e.keyCode, e.target.value);
            }
        },

        keyupHandle(e) {
            this.$emit("keyup", e);
        },

        inputHandle(e) {
            this.$emit("input", e);
            if (this.options.onInput) {
                this.options.onInput(e.target.value, this.rowIndex);
            }
        },

        focus() {
            this.$refs.input.focus();
        },

        errorIconMouseenter(event) {
            this.showErrorPanel(event);
        },

        errorIconMouseleave(event) {
            this.removeErrorPanel(event);
        },

        dblclickHandle() {
            this.$emit("dblclick", this);
        },

        clickHandle() {
            this.$emit("click", this);
        }
    }
};
</script>

<style>
.text-input {
    width: 100%;
    height: 100%;
    padding: 0;
    display: flex;
    align-items: stretch;
}

.text-input.readonly {
    color: #666;
    font-family: "Microsoft YaHei", serif;
    font-size: 12px;
    align-items: center;
}

.text-input input,
.text-input .readonly-text {
    width: 100%;
    border-radius: 4px;
    border: 1px solid #d9d9d9;
    padding-left: 8px;
    color: rgba(0, 0, 0, 0.65);
    font-family: "Microsoft YaHei", serif;
    font-size: 12px;
    height: 100%;
}

.text-input .readonly-text {
    background-color: #f4f4f4;
    display: flex;
    align-items: center;
}

.text-input.validate-error input {
    border-color: #ff6e6e;
    padding-right: 25px;
}

.text-input input:focus {
    border: 1px solid rgba(0, 122, 255, 0.5);
}

.validate-error-icon {
    margin-left: -25px;
    display: flex;
    align-items: center;
}

.validate-error-icon svg {
    height: 20px;
    cursor: pointer;
}

.text-input.invisible .readonly-text {
    background-color: transparent;
    border: none;
}
</style>