import alert from './template/alert.vue';
import Base from './base.js';
import Vue from 'vue';
import jQuery from 'jquery';

let defaultOptions = {
    message: void 0,
    height: 250
};

export default class Alert extends Base {

    constructor(props) {
        super(props);
        this.initialize(props, defaultOptions).init();
    }

    createModel() {
        let _this = this;
        return new Vue({
            el: jQuery('<alert :options="options"></alert>').appendTo('body')[0],
            components: { alert },
            data() {
                return {
                    options: _this.options
                };
            }
        });
    }

    init() {
        this.createModel();
    }


}
