<template>
    <div 
        class="checkbox-container" 
        :name="field" 
        :class="{invisible:invisible}"
        @mousedown.stop
        @click.stop
        >
        <div v-if="invisible" class="readonly-text" :title="valueText" @dblclick="dblclickHandle" @click="clickHandle"><span>{{valueText}}</span></div>
        <div v-if="!invisible && value.length > 1" class="item">
            <div
                class="checkbox"
                value="all"
                :class="{checked:allChoose}"
                @click="checkboxClickAllHandle"
            ></div>
            <span>全选</span>
        </div>
        <template v-if="!invisible"> 
            <div class="item" v-for="item in checkboxList" :key="item.value">
                <div
                    class="checkbox"
                    :value="item.value"
                    :class="{checked:item.checked==1?true:false}"
                    @click="checkboxClickHandle(item)"
                ></div>
                <span>{{item.text}}</span>
            </div>
        </template>
        <template v-if="!invisible && otherList.length > 0">
            <div v-for="item in otherList" :key="item.text+item.type" class="item other">
                <div
                    class="checkbox"
                    :value="item.value"
                    :class="{checked:item.checked==1?true:false}"
                    @click="checkboxClickHandle(item)"
                ></div>
                <span>{{item.text}}</span>
                <input type="text" maxlength="64" :readonly="readonly" v-model="item.value" @change="checkboxClickHandle(item)"/>
            </div>
        </template>
    </div>
</template>

<script>
import Vue from "vue";

export default {
    props: {
        options: Object,
        propValue: String,
        propReadonly: Boolean,
        propInvisible: {
            type: Boolean,
            default: false
        }
    },

    methods: {
        // 全选
        checkboxClickAllHandle () {
            if (this.readonly) {
                return;
            }
            this.allChoose = !this.allChoose;
            this.value.forEach(item => {
                item.checked = this.allChoose ? 1 : 0;
            });
            this.$emit("change", this.field, JSON.stringify(this.value));
            if (this.options.onAllClick) {
                this.options.onAllClick(this.value);
            }
        },

        // 选中的个数
        checkedActiveNum() {
            let activeNum = this.value.filter( item => {
                return parseInt(item.checked) === 1;
            }).length;
            this.allChoose = this.value.length === activeNum;
        },

        // 复选框单击事件
        checkboxClickHandle(item) {
            if (this.readonly) {
                return;
            }
            Vue.set(item, "checked", item.checked == 1 ? 0 : 1);
            this.checkedActiveNum();
            this.$emit("change", this.field, JSON.stringify(this.value));
            if (this.options.onClick) {
                this.options.onClick(item);
            }
        },

        clickHandle() {
            this.$emit("click", this);
        },

        dblclickHandle() {
            this.$emit("dblclick", this);
        },
    },

    data() {
        return {
            allChoose: false, // 全选
            field: this.options.field,
            readonly: this.options.readonly,
            value: this.propValue ? JSON.parse(this.propValue) : [],
            invisible: this.propInvisible
        };
    },

    computed: {
        valueText() {
            let text = this.value.reduce((total, item) => {
                if (parseInt(item.checked) === 1) {
                    if(item.type) {
                         total += item.value +',';
                    } else {
                         total += item.text + ',';
                    }
                }
                return total;
            }, '');
            return text.substr(0, text.length - 1);
        },
        
        checkboxList() {
            return this.value.filter( item =>{
                return !item.type;
            });
        },

        otherList() {
            return this.value.filter( item =>{
                return item.type;
            });
        }
    },

    watch: {
        propValue(value) {
            this.value = value ? JSON.parse(value) : [];
        },

        propInvisible(val) {
            this.invisible = val;
        }
    },

    mounted() {
        this.checkedActiveNum();
    }
};
</script>

<style scoped>
.checkbox-container {
    width: 100%;
    min-height: 50px;
    border-radius: 4px;
    border: 1px solid #d9d9d9;
    color: rgba(0, 0, 0, 0.65);
    padding: 8px 8px 0 0;
    font-family: "Microsoft YaHei", serif;
    font-size: 12px;
    display: flex;
    flex-wrap: wrap;
    height: 100%;
    border: 1px solid rgba(0, 122, 255, 0.5);
}

.checkbox-container .item {
    margin-left: 8px;
    margin-right: 0;
    margin-bottom: 8px;
}

.checkbox-container.invisible {
    height: 24px;
    min-height: auto;
    border: none;
}

.checkbox-container.invisible .readonly-text {
    width: 100%;
    height: 100%;
    border-radius: 4px;
    padding-left: 8px;
    color: rgba(0, 0, 0, 0.65);
    font-family: "Microsoft YaHei", serif;
    font-size: 12px;
    border: none;
    display: flex;
    align-items: center;
}

.checkbox-container.invisible .readonly-text>span {
    display: inline-block;
    width: 100%;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.checkbox {
    width: 14px;
    height: 14px;
    border: 1px solid #d9d9d9;
    margin-right: 5px;
    border-radius: 2px;
}

.checkbox.checked {
    background-color: #007aff;
    background-image: url("../../../../img/check-white.png");
    background-repeat: no-repeat;
    background-position: center;
    border: 1px solid #007aff;
}

.checkbox:hover {
    border: 1px solid #007aff;
    box-shadow: 0 0 3px #007aff;
    cursor: pointer;
}

.item {
    display: flex;
    align-items: center;
    margin-right: 10px;
    margin-bottom: 10px;
}

/*解决form表单下，意外影响checkbox的问题*/
div.field-container.checkbox-container .item {
    min-height: 0;
}

/* 其他的样式 */
.checkbox-container .item.other>input{
    width: 40%;
    max-width: 60px;
    font-size: 12px;
    color: rgba(0, 0, 0, 0.65);
    padding: 2px;
    border: none;
    border-bottom: 1px solid rgba(0, 0, 0, 0.65);
}
</style>