<template>
    <div>
        <table
            :style="{width:width,left:scrollLeft}"
            :class="{'filter-open':filterOpen, 'no-user-select':columnResizing}"
        >
            <thead>
                <tr>
                    <template v-for="item in propColumns">
                        <th
                            v-if="getFieldVisible(item)"
                            :key="getHeaderKey(item)"
                            :style="{width:item.width+'px'}"
                        >
                            <div v-if="propEditorInvisible && item.editor" class="editor-flag"></div>
                            <template v-if="item.checkbox || item.radio">
                                <div
                                    class="corner-marker"
                                    v-if="propShowCheckedNum && propTotalChecked.isShow"
                                >{{propTotalChecked.num}}</div>
                                <div v-if="item.checkbox" class="all-checkbox-container">
                                    <checkbox @change="checkHandle" :propChecked="allChecked"></checkbox>
                                </div>
                                <div class="filter" v-if="filter" v-show="filterOpen">
                                    <div class="container">
                                        <div class="icon close" @click="closeFilter"></div>
                                        <div class="icon reset" @click="resetFilter"></div>
                                    </div>
                                </div>
                            </template>
                            <template v-else-if="item.index">
                                <div class="index-header-cell">序号</div>
                            </template>
                            <template v-else>
                                <i
                                    class="grid-header-resize"
                                    @mousedown="dragDown($event, item)"
                                    v-if="propColumnResize"
                                ></i>
                                <div
                                    :class="{'is-sort': item.sort !== false}"
                                    :style="{textAlign:item.titleAlign}"
                                    v-html="(propI18N(item.title)+'').replace(/<\/?p>/g,'')"
                                    @click="sort(item)"
                                ></div>
                                <div
                                    class="filter"
                                    v-if="filter && filterOpen"
                                    :style="{visibility: propFixedColumn?'hidden':'visible'}"
                                >
                                    <editor
                                        :options="item"
                                        :filterOriginalData="filterOriginalData"
                                    ></editor>
                                </div>
                            </template>
                        </th>
                    </template>
                </tr>
            </thead>
        </table>
    </div>
</template>

<script>
import Gikam from "../../../core/gikam-core";
import Vue from "vue";
import filterDateField from "./filterDateField.vue";

Vue.component("filterDateField", filterDateField);

const getEditorType = (options, fieldType) => {
    let type = options.type || "text";

    if (type === "link" || type === "choose" || type === "tree") {
        type = "text";
    } else if (type === "simpleCheckbox") {
        type = "select";
        options.items = [
            { text: "", value: "" },
            { text: "是", value: "1" },
            { text: "否", value: "0" }
        ];
    }

    if (fieldType === "date" || fieldType === "dateTime") {
        type = "filterDate";
    } else if (fieldType === "number") {
        type = "number";
    }

    if (options.type === "select") {
        type = "select";
    }
    return type;
};

const getFieldMatch = (ctx, options) => {
    const fieldTypeMapper = ctx.parent.$store.state.fieldTypeMapper;
    const type = fieldTypeMapper
        ? fieldTypeMapper[options.field.toLowerCase().replace("ext$.", "")]
        : "string";
    let matchType = "SC";
    if (options.type === "select" || options.type === "simpleCheckbox") {
        matchType = "EQ";
    } else {
        matchType = {
            string: "CISC",
            number: "NEQ",
            data: "DEQ",
            dateTime: "TEQ"
        }[type];
    }
    return options.field.includes("_")
        ? options.field
        : options.field + "_" + matchType;
};

const editor = {
    functional: true,
    inject: ["grid"],
    render(h, context) {
        const options = Gikam.deepExtend(context.props.options);
        options.readonly = false;
        const fieldTypeMapper = context.parent.$store.state.fieldTypeMapper;
        let fieldType = null;
        if (options.field && fieldTypeMapper) {
            const simpleFieldName = context.props.options.field
                .toLowerCase()
                .replace("ext$.", "");
            fieldType = fieldTypeMapper[simpleFieldName];
        }

        let editor = getEditorType(options, fieldType) + "Field";

        return (
            <editor
                ref={options.field}
                options={options}
                propReadonly={false}
                propSetValueAfterChoose={true}
                propValue={
                    context.parent.requestFieldData[
                        options.field.replace("ext$.", "")
                    ]
                }
                onChange={(...args) => {
                    context.props.filterOriginalData[options.field] = args[1];
                    const data = {};
                    data[getFieldMatch(context, options)] = args[1];
                    context.parent.$store.commit("refresh", {
                        requestData: data
                    });
                }}
            ></editor>
        );
    }
};

export default {
    props: {
        propColumns: Array,
        propWidth: Number,
        propScrollLeft: Number,
        propFilter: Boolean,
        propFilterOpen: Boolean,
        propColumnResize: Boolean,
        propEditorInvisible: Boolean,
        allChecked: {
            type: Boolean,
            default: false
        },
        propTotalChecked: {
            isShow: Boolean,
            num: Number
        },
        propShowCheckedNum: Boolean,
        propFixedColumn: {
            type: Boolean,
            default: false
        }
    },

    components: { editor },

    data() {
        return {
            filterOriginalData: {}, // 快捷查询的原始条件
            initX: null,
            resizeCell: null,
            columnResizing: false,
            headerWidth: this.propWidth,
            orderField: void 0,
            orderType: void 0,
        };
    },

    computed: {
        columns() {
            return this.propColumns;
        },

        width() {
            return this.headerWidth + "px";
        },

        scrollLeft() {
            return this.propScrollLeft + "px";
        },

        filter() {
            return this.propFilter;
        },

        filterOpen() {
            return this.propFilterOpen;
        },

        requestData() {
            return this.$store.state.requestData;
        },

        //将条件转换为仅有field的映射
        requestFieldData() {
            const data = {};
            for (let field in this.requestData) {
                data[field.split("_")[0]] = this.requestData[field];
            }
            return data;
        }
    },

    methods: {
        propI18N(text) {
            return Gikam.propI18N(text);
        },

        checkHandle(checked) {
            this.$emit("allCheck", checked);
        },

        closeFilter() {
            this.$emit("filterClose");
        },

        resetFilter() {
            this.$emit("allCheck", false);
            for (let name in this.$refs) {
                this.$refs[name].value = "";
            }
        },

        dragDown(e, item) {
            this.initX = e.pageX;
            this.columnResizing = true;
            this.resizeCell = item;
            document.addEventListener("mousemove", this.dragMove, false);
            document.addEventListener("mouseup", this.dragUp, false);
        },

        dragMove(e) {
            if (!this.columnResizing) return;
            let distance = e.pageX - this.initX;
            if (Math.abs(distance) < 3) return;
            if (distance < 0 && this.resizeCell.width < 30) return;
            this.resizeCell.width += distance;
            this.headerWidth += distance;
            this.$emit("changeWidth", this.headerWidth);
            this.initX = e.pageX;
        },

        dragUp() {
            this.initX = null;
            this.columnResizing = false;
            this.resizeCell = null;
            document.removeEventListener("mousemove", this.dragMove, false);
            document.removeEventListener("mouseup", this.dragUp, false);
            this.saveColumns();
        },

        saveColumns() {
            const url =
                Gikam.IFM_CONTEXT + "/core/module/sys/page-grid-field-configs";
            const { gridId, $window } = this.$store.state;
            const columnsConfig = this.columns
                .filter(item => !item.checkbox && !item.index)
                .map(item => {
                    return {
                        field: item.field,
                        width: item.width,
                        visible: item.visible == true ? "1" : "0",
                        fixed: item.visible == true ? "1" : "0"
                    };
                });
            return Gikam.postText(
                url,
                Gikam.getJsonWrapper(
                    {
                        gridId,
                        pageId: $window.$pageId
                    },
                    ["", columnsConfig]
                )
            );
        },

        // 排序
        sort(item) {
            if (item.sort === false) {
                return;
            }
            if (this.orderField === item.field) {
                if (!this.orderType) {
                    this.orderType = "asc";
                } else {
                    this.orderType = { asc: "desc", desc: void 0 }[
                        this.orderType
                    ];
                }
            } else {
                this.orderField = item.field;
                this.orderType = "asc";
            }
            this.$emit("sortListGrid", this.orderField, this.orderType);
        },

        getHeaderKey(options) {
            if (options.field) {
                return options.field;
            }
            if (options.index) {
                return "index";
            }
            if (options.checkbox) {
                return "checkbox";
            }
            if (options.radio) {
                return "radio";
            }
        },

        getFieldVisible(options) {
            if (options.visible === undefined || options.visible === "1") {
                return true;
            }
            return false;
        }
    }
};
</script>

<style scoped>
table {
    border-collapse: collapse;
    border-spacing: 0;
    position: relative;
    table-layout: fixed;
}

table > thead > tr > th {
    position: relative;
    height: 35px;
    padding: 0 8px;
    font-weight: normal;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
    border-left: 1px solid #eee;
}

table > thead > tr > th > div {
    overflow: hidden;
}

table.filter-open > thead > tr > th {
    height: 66px;
    vertical-align: top;
    padding-top: 9px;
}

table > thead > tr > th:first-child {
    border-left: none;
}

table > thead > tr > th > .all-checkbox-container,
table > thead > tr > th > .index-header-cell {
    display: flex;
    justify-content: center;
}

table > thead > tr > th > .corner-marker {
    font-size: 12px;
    color: #ffffff;
    letter-spacing: 0;
    padding: 0 4px;
    height: 14px;
    line-height: 14px;
    position: absolute;
    top: 0;
    right: 0;
    background: #ff003c;
    border-radius: 7px;
}

table > thead {
    font-size: 14px;
    color: rgba(0, 0, 0, 0.85);
    border-bottom: 1px solid #eee;
}

table > thead > tr > th > .grid-header-resize {
    position: absolute;
    width: 6px;
    top: 0;
    bottom: 0;
    right: -3px;
    z-index: 1;
    cursor: ew-resize;
}

table > thead > tr > th:last-child > .grid-header-resize {
    display: none;
}

table > thead > tr > th .is-sort {
    padding-right: 8px;
    text-overflow: ellipsis;
    cursor: pointer;
}

table > thead > tr > th > .sort {
    position: absolute;
    top: 3px;
    right: 0;
    width: 19px;
    height: 29px;
    padding-right: 8px;
    padding-left: 3px;
    background-color: #fff;
    display: flex;
    flex-direction: column;
    justify-content: center;
    cursor: pointer;
}

.no-user-select {
    user-select: none;
}

.filter {
    padding: 9px 0 4px 0;
}

.filter > * {
    height: 24px;
}

.filter > .container {
    display: flex;
    align-items: center;
    justify-content: center;
}

.filter > .container > .icon {
    width: 12px;
    height: 12px;
    cursor: pointer;
}

.filter > .container > .icon.close {
    background: url(../img/close.svg) no-repeat center;
    margin-right: 8px;
}

.filter > .container > .icon.reset {
    background: url(../img/reset-blue.svg) no-repeat center;
}

.editor-flag {
    position: absolute;
    top: 0;
    border-style: solid;
    left: 0;
    border-width: 4px;
    border-color: #007aff transparent transparent #007aff;
}
</style>