<template>
    <Modal :options="modal" ref="modal">
        <div class="uploader" slot="modal-body">
            <div class="container">
                <div class="upload-container">
                    <scroll>
                        <div class="item" v-for="file in fileItems" :key="file.targetId">
                            <div class="info">
                                <div class="upload-file"></div>
                                <div class="message">
                                    <div class="name">{{file.name}}</div>
                                    <span class="size">{{file.size}}KB</span>
                                    <span class="status" :class="file.state">{{getFileState(file)}}</span>
                                </div>
                            </div>
                            <div class="tool">
                                <div class="process" v-show="file.state==='start'">
                                    <div class="process-value" :style="{width:file.process+'%'}">
                                        <div class="process-bar"></div>
                                    </div>
                                    <div class="value-text">{{file.process}}%</div>
                                </div>
                                <div
                                    class="upload-del"
                                    v-show="file.state==='success'"
                                    @click="delServerFile(file)"
                                >
                                    <span class="icon icon-remove" style="font-size:18px"></span>
                                </div>
                                <div
                                    class="upload-reupload"
                                    v-show="file.state==='fail'"
                                    @click="reupload(file)"
                                ></div>
                            </div>
                        </div>
                    </scroll>
                </div>

                <div
                    v-if="!(options.multiple===false && fileItems.length===1)"
                    class="item upload-button"
                    @click="selectFile()"
                >
                    <span class="upload-icon"></span>
                    <span class="text">添加附件</span>
                </div>
            </div>
        </div>
    </Modal>
</template>

<script>
import Modal from "../modal.vue";
import Gikam from "../../../core/gikam-core";
import jQuery from "jquery";

export default {
    props: {
        options: Object
    },
    inject: {
        upload: {
            default: null
        }
    },
    data() {
        let _this = this;
        return {
            modal: {
                title: "文件上传",
                width: 500,
                height: 300,
                modal: {
                    trigger(event) {
                        if (event === "afterClose") {
                            _this.upload.grid && _this.upload.grid.refresh();
                            _this.upload.trigger("afterClose", _this.fileItems);
                        }
                    }
                }
            },
            fileItems: []
        };
    },
    methods: {
        getFileState(file) {
            const state = {
                start: "正在上传",
                success: "上传成功",
                fail: "上传失败"
            };
            return file.state ? state[file.state] : "";
        },

        getFileType(type) {
            const mimeMapper = {
                image: "image/*",
                audio: "audio/*,video/*",
                pdf: "application/pdf",
                xls: "application/vnd.ms-excel",
                zip: "aplication/zip"
            };
            if (Array.isArray(type)) {
                return type
                    .reduce((total, item) => {
                        return "," + total + mimeMapper[item];
                    }, "")
                    .replace(",", "");
            } else {
                return mimeMapper[type];
            }
        },

        selectFile() {
            let _this = this;
            jQuery(
                `<input type="file"  ${
                    this.options.multiple ? "multiple" : ""
                } ${
                    this.options.accept
                        ? "accept='" +
                          this.getFileType(this.options.accept) +
                          "'"
                        : ""
                }/>`
            )
                .appendTo(this.$el.querySelector(".uploader"))
                .on("change", e => {
                    Gikam.each(e.target.files, function() {
                        _this.fileItems.push({
                            file: this,
                            targetId:
                                _this.options.dbTable +
                                "$" +
                                _this.options.bizId,
                            name: this.name,
                            size: (this.size / 1024).toFixed(2),
                            bizCategory: _this.options.bizCategory,
                            process: 0,
                            state: "start"
                        });
                    });
                    jQuery(e.target).remove();
                    let uploadFiles = _this.fileItems.filter(item => {
                        return item.state === "start";
                    });
                    _this.uploadToServer(uploadFiles);
                })
                .click();
        },

        appendDataToForm(form, data) {
            Gikam.each(data, function(key, value) {
                Gikam.isNotEmpty(value) && form.append(key, value);
            });
        },

        uploadToServer: function(uploadFiles) {
            let file = uploadFiles[0];
            let form = new FormData();
            let xhr = new XMLHttpRequest();
            let def = jQuery.Deferred();
            let _this = this;

            if (Gikam.isEmpty(uploadFiles)) {
                return def;
            }
            this.appendDataToForm(
                form,
                Gikam.extend(
                    {
                        file: file.file,
                        targetId: file.targetId,
                        name: file.name,
                        bizCategory: file.bizCategory
                    },
                    this.upload.uploadData
                )
            );
            xhr.open("post", this.options.server, true);
            xhr.upload.onprogress = function(e) {
                file.process = (e.loaded / e.total).toFixed(2) * 100;
                if (file.process === 100) {
                    file.state = "complete";
                }
            };
            xhr.onreadystatechange = function() {
                if (this.readyState !== 4) return;
                if (this.status === 200) {
                    def.resolve(this.responseText, file);
                    file.id = this.responseText;
                    file.state = "success";
                } else {
                    file.state = "fail";
                }
                uploadFiles.shift();
                if (Gikam.isNotEmpty(uploadFiles)) {
                    _this.uploadToServer(uploadFiles);
                } else {
                    _this.upload.trigger("uploadSuccess", _this.fileItems);
                    _this.upload.options.autoClose && _this.$refs.modal.close();
                }
            };
            xhr.send(form);
            return def;
        },

        delServerFile: function(file) {
            let _this = this;
            Gikam.del(
                this.options.deleteUrl,
                Gikam.getJsonWrapper(null, ["", [{ id: file.id }]])
            ).done(function() {
                _this.fileItems = _this.fileItems.filter(
                    item => item.id !== file.id
                );
            });
        },

        reupload(file) {
            this.uploadToServer([file]);
        }
    },
    components: { Modal }
};
</script>

<style scoped>
.uploader {
    height: 100%;
    width: 100%;
    padding: 16px;
}

.uploader .container {
    height: 100%;
    width: 100%;
    display: flex;
    flex-direction: column;
}
.upload-container {
    flex: 1;
    overflow-y: auto;
}

.uploader > .container .item {
    width: 100%;
    height: 48px;
    border: 1px solid #f4f4f4;
    border-bottom: none;
    background-color: #fff;
    font-size: 12px;
    position: relative;
    padding: 0 24px 0 16px;
}
.uploader > .container .item:last-child {
    border-bottom: 1px solid #f4f4f4;
}

.uploader > .container .item > .info {
    position: relative;
    float: left;
    width: 50%;
}

.uploader > .container .item > .info > .upload-file {
    position: absolute;
    width: 17px;
    height: 20px;
    top: 12px;
    background-image: url(./img/file.png);
}

.uploader > .container .item > .info > .message {
    padding-top: 8px;
    padding-left: 25px;
    line-height: 1;
}

.uploader > .container .item > .info > .message > .name {
    width: 100%;
    padding-bottom: 6px;
    color: rgba(0, 0, 0, 0.65);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.uploader > .container .item > .info > .message > .size {
    float: left;
    margin-right: 56px;
    color: rgba(0, 0, 0, 0.5);
}

.uploader > .container .item > .info > .message > .status {
    color: rgba(0, 0, 0, 0.85);
}

.uploader > .container .item > .info > .message > .status.fail {
    color: #ff3b30;
}

.uploader > .container .item > .info > .message > .status.success {
    color: #52c41a;
}

.uploader > .container .item > .tool {
    width: 50%;
    float: left;
    overflow: hidden;
}

.uploader > .container .item > .tool > .process {
    position: relative;
    width: 100%;
    padding-right: 35px;
    margin-top: 15px;
}

.uploader > .container .item > .tool > .process > .value-text {
    position: absolute;
    right: 0;
    top: 1px;
    font-size: 12px;
    color: rgba(0, 0, 0, 0.65);
}

.uploader > .container .item > .tool > .process > .process-value {
    height: 20px;
    width: 100%;
    border-radius: 10px;
    background-color: #52c41a;
}

.uploader
    > .container
    .item
    > .tool
    > .process
    > .process-value
    > .process-bar {
    background-color: #d9d9d9;
    height: 100%;
    border-radius: 10px;
    width: 0;
}
.uploader > .container .item > .tool > .upload-del,
.uploader > .container .item > .tool > .upload-reupload {
    width: 16px;
    height: 16px;
    float: right;
    margin-top: 16px;
    cursor: pointer;
}

.uploader > .container .item > .tool > .upload-reupload {
    background-image: url(./img/reupload.png);
}

.uploader > .container > .item.upload-button {
    width: 100%;
    height: 28px;
    line-height: 28px;
    border: 1px solid #d9d9d9;
    background-color: #fff;
    text-align: center;
    color: rgba(0, 0, 0, 0.65);
    cursor: pointer;
    margin-top: 16px;
}

.uploader > .container > .item.upload-button > .text {
    font-size: 14px;
}

.uploader > .container > .item.upload-button > .upload-icon {
    display: inline-block;
    width: 16px;
    height: 16px;
    background-image: url(./img/upload.png);
    vertical-align: text-bottom;
    margin-right: 8px;
}
</style>
<style>
.uploader > input {
    display: none;
}

.uploader > .grid {
    padding: 0;
    padding-top: 8px;
}

.uploader > .grid > .toolbar {
    padding-left: 8px;
    padding-right: 8px;
}

.uploader > .grid > .grid-body,
.uploader > .grid > .grid-header {
    border-left: none;
    border-right: none;
}

.uploader > .grid > .grid-footer {
    padding-bottom: 0;
    border: none;
}
</style>

