<!-- cron命令生成器组件 -->
<template>
    <div class="container" @mousedown.stop>
        <div class="cron-container">
            <!-- tab导航 -->
            <div class="cron-nav">
                <span
                    :class="{active: tabDefault === item.key}"
                    v-for="item in tabText"
                    :key="item.key"
                    @click="tabChange(item.key)"
                >{{item.key}}</span>
            </div>
            <div class="cron-choose">
                <scroll>
                    <!-- 秒 -->
                    <div class="cron-item" v-show="tabDefault === '秒'">
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="seconds"
                                value="wildcard"
                                v-model="seconds.radio"
                            />
                            <span>每秒允许的通配符[, - * /]</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="seconds"
                                value="period"
                                v-model="seconds.radio"
                            />
                            <span>周期从</span>
                            <input
                                type="number"
                                max="58"
                                min="1"
                                v-model="seconds.periodStart"
                                @change="minmaxValue(58, 1, seconds.periodStart, 'seconds', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="59"
                                min="2"
                                v-model="seconds.periodEnd"
                                @change="minmaxValue(59, 2, seconds.periodEnd, 'seconds', 'periodEnd')"
                            />
                            <span>秒</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="seconds"
                                value="executeone"
                                v-model="seconds.radio"
                            />
                            <span>从</span>
                            <input
                                type="number"
                                max="59"
                                min="0"
                                v-model="seconds.executeoneStart"
                                @change="minmaxValue(59, 0, seconds.executeoneStart, 'seconds', 'executeoneStart')"
                            />
                            <span>秒开始，每</span>
                            <input
                                type="number"
                                max="59"
                                min="1"
                                v-model="seconds.executeoneEnd"
                                @change="minmaxValue(59, 1, seconds.executeoneEnd, 'seconds', 'executeoneEnd')"
                            />
                            <span>秒执行一次</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="seconds"
                                value="appoint"
                                v-model="seconds.radio"
                            />
                            <span>指定</span>
                            <div class="appoint-checkbox">
                                <span class="item-checkbox" v-for="(item, index) in 60" :key="item">
                                    <input type="checkbox" :value="index" v-model="seconds.appoint" />
                                    <span>{{index > 9 ? index : '0' + index}}</span>
                                </span>
                            </div>
                        </div>
                    </div>
                    <!-- 分 -->
                    <div class="cron-item" v-show="tabDefault === '分'">
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="minutes"
                                value="wildcard"
                                v-model="minutes.radio"
                            />
                            <span>分钟允许的通配符[, - * /]</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="minutes"
                                value="period"
                                v-model="minutes.radio"
                            />
                            <span>周期从</span>
                            <input
                                type="number"
                                max="58"
                                min="1"
                                v-model="minutes.periodStart"
                                @change="minmaxValue(58, 1, minutes.periodStart, 'minutes', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="59"
                                min="2"
                                v-model="minutes.periodEnd"
                                @change="minmaxValue(59, 2, minutes.periodEnd, 'minutes', 'periodEnd')"
                            />
                            <span>分钟</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="minutes"
                                value="executeone"
                                v-model="minutes.radio"
                            />
                            <span>从</span>
                            <input
                                type="number"
                                max="59"
                                min="0"
                                v-model="minutes.executeoneStart"
                                @change="minmaxValue(59, 0, minutes.executeoneStart, 'minutes', 'executeoneStart')"
                            />
                            <span>分钟开始，每</span>
                            <input
                                type="number"
                                max="59"
                                min="1"
                                v-model="minutes.executeoneEnd"
                                @change="minmaxValue(59, 1, minutes.executeoneEnd, 'minutes', 'executeoneEnd')"
                            />
                            <span>分钟执行一次</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="minutes"
                                value="appoint"
                                v-model="minutes.radio"
                            />
                            <span>指定</span>
                            <div class="appoint-checkbox">
                                <span class="item-checkbox" v-for="(item, index) in 60" :key="item">
                                    <input
                                        type="checkbox"
                                        name="minutesCheckbox"
                                        :value="index"
                                        v-model="minutes.appoint"
                                    />
                                    <span>{{index > 9 ? index : '0' + index}}</span>
                                </span>
                            </div>
                        </div>
                    </div>
                    <!-- 时 -->
                    <div class="cron-item" v-show="tabDefault === '时'">
                        <div class="choose-item">
                            <input type="radio" name="hour" value="wildcard" v-model="hour.radio" />
                            <span>小时允许的通配符[, - * /]</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="hour" value="period" v-model="hour.radio" />
                            <span>周期从</span>
                            <input
                                type="number"
                                max="23"
                                min="0"
                                v-model="hour.periodStart"
                                @change="minmaxValue(23, 0, hour.periodStart, 'hour', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="23"
                                min="2"
                                v-model="hour.periodEnd"
                                @change="minmaxValue(23, 2, hour.periodEnd, 'hour', 'periodEnd')"
                            />
                            <span>小时</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="hour" value="executeone" v-model="hour.radio" />
                            <span>从</span>
                            <input
                                type="number"
                                max="23"
                                min="0"
                                v-model="hour.executeoneStart"
                                @change="minmaxValue(23, 0, hour.executeoneStart, 'hour', 'executeoneStart')"
                            />
                            <span>小时开始，每</span>
                            <input
                                type="number"
                                max="23"
                                min="1"
                                v-model="hour.executeoneEnd"
                                @change="minmaxValue(23, 1, hour.executeoneEnd, 'hour', 'executeoneEnd')"
                            />
                            <span>小时执行一次</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="hour" value="appoint" v-model="hour.radio" />
                            <span>指定</span>
                            <div class="appoint-checkbox">
                                <div class="hour-AM">
                                    <span>AM：</span>
                                    <span
                                        class="item-checkbox"
                                        v-for="(item, index) in 12"
                                        :key="item"
                                    >
                                        <input
                                            type="checkbox"
                                            name="hourCheckbox"
                                            :value="index"
                                            v-model="hour.appoint"
                                        />
                                        <span>{{index > 9 ? index : '0' + index}}</span>
                                    </span>
                                </div>
                                <div class="hour-PM">
                                    <span>PM：</span>
                                    <template v-for="(item, index) in 24">
                                        <span class="item-checkbox" :key="item" v-if="index > 11">
                                            <input
                                                type="checkbox"
                                                name="hourCheckbox"
                                                :value="index"
                                                v-model="hour.appoint"
                                            />
                                            <span>{{index > 9 ? index : '0' + index}}</span>
                                        </span>
                                    </template>
                                </div>
                            </div>
                        </div>
                    </div>
                    <!-- 日 -->
                    <div class="cron-item" v-show="tabDefault === '日'">
                        <div class="choose-item">
                            <input type="radio" name="days" value="wildcard" v-model="days.radio" />
                            <span>日允许的通配符[, - * / L W]</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="days" value="noappoint" v-model="days.radio" />
                            <span>不指定</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="days" value="period" v-model="days.radio" />
                            <span>周期从</span>
                            <input
                                type="number"
                                max="31"
                                min="1"
                                v-model="days.periodStart"
                                @change="minmaxValue(31, 1, days.periodStart, 'days', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="31"
                                min="2"
                                v-model="days.periodEnd"
                                @change="minmaxValue(31, 2, days.periodEnd, 'days', 'periodEnd')"
                            />
                            <span>日</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="days" value="executeone" v-model="days.radio" />
                            <span>从</span>
                            <input
                                type="number"
                                max="31"
                                min="1"
                                v-model="days.executeoneStart"
                                @change="minmaxValue(31, 1, days.executeoneStart, 'days', 'executeoneStart')"
                            />
                            <span>日开始，每</span>
                            <input
                                type="number"
                                max="31"
                                min="1"
                                v-model="days.executeoneEnd"
                                @change="minmaxValue(31, 1, days.executeoneEnd, 'days', 'executeoneEnd')"
                            />
                            <span>天执行一次</span>
                        </div>
                        <!-- <div class="choose-item">
                            <input type="radio" name='days' value="workday" v-model="days.radio" /><span>每月</span>
                            <input type="number" max="31" min="1" v-model="days.workDay" @change="minmaxValue(31, 1, days.workDay, 'days', 'workDay')" /><span>号最近的那个工作日</span>
                        </div>-->
                        <div class="choose-item">
                            <input type="radio" name="days" value="lastday" v-model="days.radio" />
                            <span>本月最后一天</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="days" value="appoint" v-model="days.radio" />
                            <span>指定</span>
                            <div class="appoint-checkbox">
                                <span class="item-checkbox" v-for="item in 31" :key="item">
                                    <input
                                        type="checkbox"
                                        name="riCheckbox"
                                        :value="item"
                                        v-model="days.appoint"
                                    />
                                    <span>{{item > 9 ? item : '0' + item}}</span>
                                </span>
                            </div>
                        </div>
                    </div>
                    <!-- 月 -->
                    <div class="cron-item" v-show="tabDefault === '月'">
                        <div class="choose-item">
                            <input type="radio" name="month" value="wildcard" v-model="month.radio" />
                            <span>月允许的通配符[, - * /]</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="month"
                                value="noappoint"
                                v-model="month.radio"
                            />
                            <span>不指定</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="month" value="period" v-model="month.radio" />
                            <span>周期从</span>
                            <input
                                type="number"
                                max="12"
                                min="1"
                                v-model="month.periodStart"
                                @change="minmaxValue(12, 1, month.periodStart, 'month', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="12"
                                min="2"
                                v-model="month.periodEnd"
                                @change="minmaxValue(12, 2, month.periodEnd, 'month', 'periodEnd')"
                            />
                            <span>月</span>
                        </div>
                        <div class="choose-item">
                            <input
                                type="radio"
                                name="month"
                                value="executeone"
                                v-model="month.radio"
                            />
                            <span>从</span>
                            <input
                                type="number"
                                max="12"
                                min="1"
                                v-model="month.executeoneStart"
                                @change="minmaxValue(12, 1, month.executeoneStart, 'month', 'executeoneStart')"
                            />
                            <span>月开始，每</span>
                            <input
                                type="number"
                                min="1"
                                v-model="month.executeoneEnd"
                                @change="minmaxValue(Infinity, 1, month.executeoneEnd, 'month', 'executeoneEnd')"
                            />
                            <span>月执行一次</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="month" value="appoint" v-model="month.radio" />
                            <span>指定</span>
                            <div class="appoint-checkbox">
                                <span class="item-checkbox" v-for="item in 12" :key="item">
                                    <input
                                        type="checkbox"
                                        name="monthCheckbox"
                                        :value="item"
                                        v-model="month.appoint"
                                    />
                                    <span>{{item > 9 ? item : '0' + item}}</span>
                                </span>
                            </div>
                        </div>
                    </div>
                    <!-- 周 -->
                    <div class="cron-item" v-show="tabDefault === '周'">
                        <div class="choose-item">
                            <input type="radio" name="week" value="wildcard" v-model="week.radio" />
                            <span>周允许的通配符[, - * / L #]</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="week" value="noappoint" v-model="week.radio" />
                            <span>不指定</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="week" value="period" v-model="week.radio" />
                            <span>周期从星期</span>
                            <input
                                type="number"
                                max="7"
                                min="1"
                                v-model="week.periodStart"
                                @change="minmaxValue(7, 1, week.periodStart, 'week', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="7"
                                min="2"
                                v-model="week.periodEnd"
                                @change="minmaxValue(7, 2, week.periodEnd, 'week', 'periodEnd')"
                            />
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="week" value="countweek" v-model="week.radio" />
                            <span>第</span>
                            <input
                                type="number"
                                max="5"
                                min="1"
                                v-model="week.countWeek"
                                @change="minmaxValue(5, 1, week.countWeek, 'week', 'countWeek')"
                            />
                            <span>周的星期</span>
                            <input
                                type="number"
                                max="7"
                                min="1"
                                v-model="week.whatDay"
                                @change="minmaxValue(7, 1, week.whatDay, 'week', 'whatDay')"
                            />
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="week" value="lastweek" v-model="week.radio" />
                            <span>本月最后一个星期</span>
                            <input
                                type="number"
                                max="7"
                                min="1"
                                v-model="week.lastDay"
                                @change="minmaxValue(7, 1, week.lastDay, 'week', 'lastDay')"
                            />
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="week" value="appoint" v-model="week.radio" />
                            <span>指定</span>
                            <div class="appoint-checkbox">
                                <span class="item-checkbox" v-for="item in 7" :key="item">
                                    <input
                                        type="checkbox"
                                        name="weekCheckbox"
                                        :value="weekDay(item)"
                                        v-model="week.appoint"
                                    />
                                    <span>{{item}}</span>
                                </span>
                            </div>
                        </div>
                    </div>
                    <!-- 年 -->
                    <div class="cron-item" v-show="tabDefault === '年'">
                        <div class="choose-item">
                            <input type="radio" name="year" value="nowildcard" v-model="year.radio" />
                            <span>不指定允许的通配符[, - * /] 非必填</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="year" value="peryear" v-model="year.radio" />
                            <span>每年</span>
                        </div>
                        <div class="choose-item">
                            <input type="radio" name="year" value="period" v-model="year.radio" />
                            <span>周期从</span>
                            <input
                                type="number"
                                max="3000"
                                min="2013"
                                v-model="year.periodStart"
                                @change="minmaxValue(3000, 2013, year.periodStart, 'year', 'periodStart')"
                            />
                            <span>-</span>
                            <input
                                type="number"
                                max="3000"
                                min="2014"
                                v-model="year.periodEnd"
                                @change="minmaxValue(3000, 2014, year.periodEnd, 'year', 'periodEnd')"
                            />
                        </div>
                        <div class="choose-item mb12">
                            <input type="radio" name="year" value="executeone" v-model="year.radio" />
                            <span>从</span>
                            <input
                                type="number"
                                max="3000"
                                min="2014"
                                v-model="year.executeoneStart"
                                @change="minmaxValue(3000, 2014, year.executeoneStart, 'year', 'executeoneStart')"
                            />
                            <span>年开始，每</span>
                            <input
                                type="number"
                                max="100"
                                min="1"
                                v-model="year.executeoneEnd"
                                @change="minmaxValue(100, 1, year.executeoneEnd, 'year', 'executeoneEnd')"
                            />
                            <span>年执行一次</span>
                        </div>
                    </div>
                </scroll>
            </div>
            <!-- 结果 -->
            <div class="cron-result-container">
                <div class="cron-result">
                    <span class="result-text expression">表达式字段：</span>
                    <div class="result-items">
                        <div class="result-item" v-for="item in tabText" :key="item.key">
                            <span v-if="item.key === '分'">分钟</span>
                            <span v-else-if="item.key === '时'">小时</span>
                            <span v-else-if="item.key === '周'">星期</span>
                            <span v-else>{{item.key}}</span>
                            <input type="text" readonly v-model="item.value" />
                        </div>
                    </div>
                </div>
                <div class="cron-result">
                    <span class="result-text">Cron表达式：</span>
                    <input type="text" class="analysis-input" v-model="cronExpression" />
                    <span class="analysis-ul" @click="analysisUiFn">反解析到UI</span>
                </div>
                <!-- <div class="cron-result">
                        <span class="result-text runtime-Tit">最近5次运行时间：</span>
                        <span class="runtime-cont">
                            <p class="runtime">2019-09-03 10:32:33</p>
                            <p class="runtime">2019-09-03 10:32:33</p>
                            <p class="runtime">2019-09-03 10:32:33</p>
                            <p class="runtime">2019-09-03 10:32:33</p>
                            <p class="runtime">2019-09-03 10:32:33</p>
                        </span>
                </div>-->
            </div>
        </div>
    </div>
</template>

<script>
import Gikam from "../../../../core/gikam-core";

export default {
    name: "cron",
    props: {
        value: String
    },

    data() {
        return {
            tabDefault: "秒",
            cronExpression: this.value, // cron表达式
            tabText: [
                {
                    key: "秒",
                    value: "*"
                },
                {
                    key: "分",
                    value: "*"
                },
                {
                    key: "时",
                    value: "*"
                },
                {
                    key: "日",
                    value: "*"
                },
                {
                    key: "月",
                    value: "*"
                },
                {
                    key: "周",
                    value: "?"
                },
                {
                    key: "年",
                    value: ""
                }
            ],
            seconds: {
                radio: "wildcard",
                periodStart: 1, // 周期从-开始
                periodEnd: 2, // 周期从-结束
                executeoneStart: 0, // 执行一次-开始
                executeoneEnd: 1, // 执行一次-结束
                appoint: [] //  指定
            },
            minutes: {
                radio: "wildcard",
                periodStart: 1,
                periodEnd: 2,
                executeoneStart: 0,
                executeoneEnd: 1,
                appoint: []
            },
            hour: {
                radio: "wildcard",
                periodStart: 0,
                periodEnd: 2,
                executeoneStart: 0,
                executeoneEnd: 1,
                appoint: []
            },
            days: {
                radio: "wildcard",
                periodStart: 1,
                periodEnd: 2,
                executeoneStart: 1,
                executeoneEnd: 1,
                // workDay: 1, // 最近的工作日
                appoint: []
            },
            month: {
                radio: "wildcard",
                periodStart: 1,
                periodEnd: 2,
                executeoneStart: 1,
                executeoneEnd: 1,
                appoint: []
            },
            week: {
                radio: "noappoint",
                periodStart: 1,
                periodEnd: 2,
                countWeek: 1, // 第几周
                whatDay: 1, // 星期几
                lastDay: 2, // 最近的工作日
                appoint: []
            },
            year: {
                radio: "nowildcard",
                periodStart: 2013,
                periodEnd: 2014,
                executeoneStart: 2014,
                executeoneEnd: 1
            }
        };
    },

    watch: {
        tabText: {
            handler(val) {
                this.cronExpressionFn(val);
            },
            deep: true
        },
        seconds: {
            handler(val) {
                let tabData = this.chooseRadioVal("seconds");
                this.chooseTabText(0, tabData[val.radio]);
            },
            deep: true
        },
        "seconds.radio"(val) {
            if (val === "appoint" && this.seconds.appoint.length === 0)
                this.appointInitial("seconds", [0]);
        },
        "seconds.appoint"(val) {
            if (this.seconds.radio === "appoint" && val.length === 0)
                this.chooseTabText(0, "?");
        },
        minutes: {
            handler(val) {
                let tabData = this.chooseRadioVal("minutes");
                this.chooseTabText(1, tabData[val.radio]);
            },
            deep: true
        },
        "minutes.radio"(val) {
            if (val === "appoint" && this.minutes.appoint.length === 0)
                this.appointInitial("minutes", [0]);
        },
        "minutes.appoint"(val) {
            if (this.minutes.radio === "appoint" && val.length === 0)
                this.chooseTabText(1, "?");
        },
        hour: {
            handler(val) {
                let tabData = this.chooseRadioVal("hour");
                this.chooseTabText(2, tabData[val.radio]);
            },
            deep: true
        },
        "hour.radio"(val) {
            if (val === "appoint" && this.hour.appoint.length === 0)
                this.appointInitial("hour", [0]);
        },
        "hour.appoint"(val) {
            if (this.hour.radio === "appoint" && val.length === 0)
                this.chooseTabText(2, "?");
        },
        days: {
            handler(val) {
                let tabData = this.chooseRadioVal("days");
                this.chooseTabText(3, tabData[val.radio]);
            },
            deep: true
        },
        "days.radio"(val) {
            if (val === "appoint" && this.days.appoint.length === 0)
                this.appointInitial("days", [1]);
        },
        "days.appoint"(val) {
            if (this.days.radio === "appoint" && val.length === 0)
                this.chooseTabText(3, "?");
        },
        month: {
            handler(val) {
                let tabData = this.chooseRadioVal("month");
                this.chooseTabText(4, tabData[val.radio]);
                if (this.month.executeoneEnd > 99999999) {
                    this.month.executeoneEnd = (
                        this.month.executeoneEnd + ""
                    ).slice(0, 8);
                }
            },
            deep: true
        },
        "month.radio"(val) {
            if (val === "appoint" && this.month.appoint.length === 0)
                this.appointInitial("month", [1]);
        },
        "month.appoint"(val) {
            if (this.month.radio === "appoint" && val.length === 0)
                this.chooseTabText(4, "?");
        },
        week: {
            handler(val) {
                let tabData = this.chooseRadioVal("week");
                this.chooseTabText(5, tabData[val.radio]);
            },
            deep: true
        },
        "week.radio"(val) {
            if (val === "appoint" && this.week.appoint.length === 0)
                this.appointInitial("week", [2]);
        },
        "week.appoint"(val) {
            if (this.month.radio === "appoint" && val.length === 0)
                this.chooseTabText(5, "?");
        },
        year: {
            handler(val) {
                let tabData = this.chooseRadioVal("year");
                this.chooseTabText(6, tabData[val.radio]);
            },
            deep: true
        }
    },

    methods: {
        // 点击tab
        tabChange(tab) {
            if (tab === "日" && this.week.radio !== "noappoint") {
                Gikam.alert("请将周设置为“不指定”，再设置日");
                this.tabDefault = "周";
                return;
            }

            if (tab === "周" && this.days.radio !== "noappoint") {
                Gikam.alert("请将日设置为“不指定”，再设置周");
                this.tabDefault = "日";
                return;
            }
            this.tabDefault = tab;
        },
        // tabText的value数据赋值
        chooseTabText(index, data) {
            this.$set(this.tabText[index], "value", data);
        },
        // 选中指定，复选框无值，自动选中
        appointInitial(tab, array) {
            this.$set(this[tab], "appoint", array);
        },
        // 反解析到UI
        analysisUiFn() {
            let valueArray = this.cronExpression.trim().split(" ");
            this.analysisUiStepFn("seconds", valueArray[0]);
            this.analysisUiStepFn("minutes", valueArray[1]);
            this.analysisUiStepFn("hour", valueArray[2]);
            this.analysisUiStepFn("days", valueArray[3]);
            this.analysisUiStepFn("month", valueArray[4]);
            this.analysisUiStepFn("week", valueArray[5]);
            this.analysisUiStepFn("year", valueArray[6]);
        },
        analysisUiStepFn(tab, value) {
            if (!value) {
                this[tab].radio = "nowildcard";
                return;
            } else if (tab !== "year" && value.indexOf("*") > -1) {
                this[tab].radio = "wildcard";
                return;
            } else if (value.indexOf("-") > -1) {
                this[tab].radio = "period";
                this[tab].periodStart = value.split("-")[0];
                this[tab].periodEnd = value.split("-")[1];
                if (tab === "week") {
                    this[tab].periodStart = this.reverseWeekDay(
                        value.split("-")[0]
                    );
                    this[tab].periodEnd = this.reverseWeekDay(
                        value.split("-")[1]
                    );
                }
                return;
            } else if (value.indexOf("/") > -1) {
                this[tab].radio = "executeone";
                this[tab].executeoneStart = value.split("/")[0];
                this[tab].executeoneEnd = value.split("/")[1];
                return;
            } else if (value.indexOf("/") > -1) {
                this[tab].radio = "executeone";
                this[tab].executeoneStart = value.split("/")[0];
                this[tab].executeoneEnd = value.split("/")[1];
                return;
            } else if (value === "?") {
                this[tab].radio = "noappoint";
                return;
            }
            // else if (value.indexOf('W') > -1) {
            //     this[tab].radio = 'workday';
            //     this[tab].workDay = value.split('W')[0];
            //     return;
            // }
            else if (value === "L") {
                this[tab].radio = "lastday";
                return;
            } else if (value.indexOf("#") > -1) {
                this[tab].radio = "countweek";
                this[tab].countWeek = value.split("#")[1];
                this[tab].whatDay = value.split("#")[0] - 1;
                return;
            } else if (value.length > 1 && value.indexOf("L") > -1) {
                this[tab].radio = "lastweek";
                this[tab].lastDay = this.reverseWeekDay(value.split("L")[0]);
                return;
            } else if (tab === "year" && value === "*") {
                this[tab].radio = "peryear";
                return;
            } else {
                this[tab].radio = "appoint";
                this[tab].appoint = value.split(",");
                return;
            }
        },
        // cron表达式赋值
        cronExpressionFn(val) {
            this.cronExpression = val
                .reduce((total, item) => {
                    return total + item.value + " ";
                }, "")
                .trim();
        },
        // 选择radio的value
        chooseRadioVal(tab) {
            let period = this[tab].periodStart + "-" + this[tab].periodEnd;
            if (tab === "week") {
                period =
                    this.weekDay(this[tab].periodStart) +
                    "-" +
                    this.weekDay(this[tab].periodEnd);
            }
            return {
                wildcard: "*",
                period: period,
                executeone:
                    this[tab].executeoneStart + "/" + this[tab].executeoneEnd,
                appoint: this[tab].appoint,
                noappoint: "?",
                // workday: this[tab].workDay + 'W',
                lastday: "L",
                countweek:
                    this.weekDay(this[tab].whatDay) + "#" + this[tab].countWeek,
                lastweek: this.weekDay(this[tab].lastDay) + "L",
                nowildcard: "",
                peryear: "*"
            };
        },
        // 周做处理 周几+1，周7=1
        weekDay(day) {
            let D = day == 7 ? 1 : day + 1;
            return D;
        },
        // 反解析周
        reverseWeekDay(day) {
            let D = day == 1 ? 7 : day - 1;
            return D;
        },
        // 数值优化-最小值-最大值
        minmaxValue(max, min, num, tab, key) {
            let number = Math.round(num);
            if (number > max) {
                this[tab][key] = max;
            } else if (number < min) {
                this[tab][key] = min;
            } else {
                this[tab][key] = Math.round(number);
            }
        }
    },

    mounted() {
        this.$nextTick(() => {
            !this.cronExpression && this.cronExpressionFn(this.tabText);
            this.cronExpression && this.analysisUiFn();
        });
    }
};
</script>

