<template>
    <div class="edit-toolbar">
        <div class="btn plus" title="新增节点" @click.stop="click('insert')"></div>
        <div class="btn edit" title="编辑节点" @click.stop="click('edit')"></div>
        <div class="btn remove" title="删除节点" @click.stop="click('remove')"></div>
    </div>
</template>

<script>
export default {
    props: {
        options: Object
    },

    methods: {
        click(type) {
            this.$emit("click", type,this.options);
        }
    }
};
</script>

<style scoped>
.edit-toolbar {
    display: flex;
    position: relative;
    width: 70px;
}

.edit-toolbar > .btn {
    width: 16px;
    height: 16px;
    cursor: pointer;
    padding-right: 15px;
}

.edit-toolbar .plus {
    background: url(img/plus.svg) no-repeat center;
}

.edit-toolbar .edit {
    background: url(img/node-edit.svg) no-repeat center;
}

.edit-toolbar .remove {
    background: url(img/remove.svg) no-repeat center;
}
</style>